package io.github.testlens.migration.tooling;

import io.github.testlens.compatibility.engine.ComparisonIntent;
import io.github.testlens.compatibility.engine.CompatibilityComparisonReport;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

/** Canonical sanitized final report for one source-apply transaction. Exact source/diff bytes stay separate. */
public record MigrationApplyReport(int schemaVersion,int algorithmVersion,String reportId,String repositoryBindingRef,
        String worktreeBindingRef,String proposalSetRef,List<String>selectedProposalIds,List<String>decisionRefs,
        String applyPlanRef,String transactionRef,Status status,MigrationApplyResult.Status applyStatus,
        List<ProposalSummary>proposals,List<FileSummary>files,List<TransactionEventSummary>transactionEvents,String postApplyCheckpointRef,
        MigrationRecoverySummary recoverySummary,String recoveryActionPlanRef,VerificationCoverage verification,
        String acceptedVerificationResultRef,List<String>verificationHistoryRefs,List<String>compatibilityEvidenceRefs,
        String ownedDiffRef,String ownedDiffDigest,long ownedDiffBytes,PreExistingUserState preExistingUserState,
        IndexState currentIndex,CurrentStateRelation currentStateRelation,MigrationCommitReadiness commitReadiness,
        List<NextAction>nextActions,List<String>limitations,List<MigrationReleaseGap>knownNotRun,List<String>issues,
        String releaseHardeningHandoffRef){
    public static final int MAX_BYTES=64*1024*1024,MAX_PROPOSALS=32,MAX_FILES=64,MAX_STAGES=512,MAX_GAPS=128,MAX_ISSUES=1024;
    public MigrationApplyReport{if(schemaVersion!=1||algorithmVersion!=1)throw new IllegalArgumentException("report version");MigrationApplyPlan.require(repositoryBindingRef,"migration-repository-binding-v1");MigrationApplyPlan.require(worktreeBindingRef,"migration-worktree-binding-v1");MigrationApplyPlan.require(proposalSetRef,"migration-proposal-set-v1");MigrationApplyPlan.require(applyPlanRef,"migration-apply-plan-v1");MigrationApplyPlan.require(transactionRef,"migration-apply-transaction-v1");Objects.requireNonNull(status);Objects.requireNonNull(applyStatus);selectedProposalIds=ids(selectedProposalIds);decisionRefs=ids(decisionRefs);proposals=proposals==null?List.of():proposals.stream().sorted(Comparator.comparing(ProposalSummary::proposalId)).toList();files=files==null?List.of():files.stream().sorted(Comparator.comparing(FileSummary::logicalPath)).toList();transactionEvents=transactionEvents==null?List.of():transactionEvents.stream().sorted(Comparator.comparingLong(TransactionEventSummary::sequence)).toList();if(postApplyCheckpointRef!=null)MigrationApplyPlan.require(postApplyCheckpointRef,"migration-checkpoint-v1");Objects.requireNonNull(recoverySummary);MigrationApplyPlan.require(recoveryActionPlanRef,"migration-recovery-action-plan-v1");Objects.requireNonNull(verification);if(acceptedVerificationResultRef!=null)MigrationApplyPlan.require(acceptedVerificationResultRef,"migration-verification-result-v1");verificationHistoryRefs=ids(verificationHistoryRefs);compatibilityEvidenceRefs=ids(compatibilityEvidenceRefs);ownedDiffRef=MigrationRunPlan.logical(ownedDiffRef);MigrationApplyPlan.require(ownedDiffDigest,"sha256");if(ownedDiffBytes<0||ownedDiffBytes>MigrationApplyPlan.MAX_DIFF_BYTES)throw new IllegalArgumentException("diff bytes");Objects.requireNonNull(preExistingUserState);Objects.requireNonNull(currentIndex);Objects.requireNonNull(currentStateRelation);Objects.requireNonNull(commitReadiness);nextActions=nextActions==null?List.of():nextActions.stream().distinct().sorted().toList();limitations=strings(limitations);knownNotRun=knownNotRun==null?List.of():knownNotRun.stream().sorted(Comparator.comparing(MigrationReleaseGap::gapCode)).toList();issues=strings(issues);MigrationApplyPlan.require(releaseHardeningHandoffRef,"migration-release-hardening-handoff-v1");if(proposals.size()>MAX_PROPOSALS||files.size()>MAX_FILES||verification.stages().size()>MAX_STAGES||knownNotRun.size()>MAX_GAPS||issues.size()>MAX_ISSUES||transactionEvents.size()>2048)throw new IllegalArgumentException("report bound");String expected=id(repositoryBindingRef,worktreeBindingRef,proposalSetRef,selectedProposalIds,decisionRefs,applyPlanRef,transactionRef,status,applyStatus,proposals,files,transactionEvents,postApplyCheckpointRef,recoverySummary,recoveryActionPlanRef,verification,acceptedVerificationResultRef,verificationHistoryRefs,compatibilityEvidenceRefs,ownedDiffRef,ownedDiffDigest,ownedDiffBytes,preExistingUserState,currentIndex,currentStateRelation,commitReadiness,nextActions,limitations,knownNotRun,issues,releaseHardeningHandoffRef);if(!expected.equals(reportId))throw new IllegalArgumentException("reportId");}
    public static MigrationApplyReport create(String repo,String worktree,String proposalSet,List<String>selected,List<String>decisions,String applyPlan,String tx,Status status,MigrationApplyResult.Status applyStatus,List<ProposalSummary>proposals,List<FileSummary>files,List<TransactionEventSummary>events,String postCheckpoint,MigrationRecoverySummary recovery,String actionPlan,VerificationCoverage verification,String accepted,List<String>history,List<String>evidence,String diffRef,String diffDigest,long diffBytes,PreExistingUserState pre,IndexState index,CurrentStateRelation relation,MigrationCommitReadiness readiness,List<NextAction>actions,List<String>limitations,List<MigrationReleaseGap>gaps,List<String>issues,String handoff){selected=ids(selected);decisions=ids(decisions);proposals=proposals==null?List.of():proposals.stream().sorted(Comparator.comparing(ProposalSummary::proposalId)).toList();files=files==null?List.of():files.stream().sorted(Comparator.comparing(FileSummary::logicalPath)).toList();events=events==null?List.of():events.stream().sorted(Comparator.comparingLong(TransactionEventSummary::sequence)).toList();history=ids(history);evidence=ids(evidence);actions=actions==null?List.of():actions.stream().distinct().sorted().toList();limitations=strings(limitations);gaps=gaps==null?List.of():gaps.stream().sorted(Comparator.comparing(MigrationReleaseGap::gapCode)).toList();issues=strings(issues);String id=id(repo,worktree,proposalSet,selected,decisions,applyPlan,tx,status,applyStatus,proposals,files,events,postCheckpoint,recovery,actionPlan,verification,accepted,history,evidence,diffRef,diffDigest,diffBytes,pre,index,relation,readiness,actions,limitations,gaps,issues,handoff);return new MigrationApplyReport(1,1,id,repo,worktree,proposalSet,selected,decisions,applyPlan,tx,status,applyStatus,proposals,files,events,postCheckpoint,recovery,actionPlan,verification,accepted,history,evidence,diffRef,diffDigest,diffBytes,pre,index,relation,readiness,actions,limitations,gaps,issues,handoff);}
    public enum Status{APPLIED_VERIFIED,APPLIED_VERIFICATION_FAILED,APPLIED_VERIFICATION_INCONCLUSIVE,APPLIED_VERIFICATION_BLOCKED,PARTIAL_APPLY,ROLLED_BACK,PARTIAL_ROLLBACK,RECOVERY_REQUIRED,CURRENT_STATE_DIVERGED}
    public enum CurrentStateRelation{MATCHES_VERIFIED_STATE,MATCHES_APPLIED_UNVERIFIED_STATE,RESTORED_TO_ORIGINAL,USER_MODIFIED_AFTER_APPLY,PARTIAL_APPLY_STATE,RECOVERY_REQUIRED,UNKNOWN}
    public enum CurrentFileState{CURRENT_TOOL_APPLIED,CURRENT_ORIGINAL,CURRENT_USER_MODIFIED,CURRENT_MISSING,CURRENT_UNKNOWN}
    public enum RollbackState{AVAILABLE,ALREADY_ORIGINAL,BLOCKED_USER_MODIFICATION,BLOCKED_MISSING,BACKUP_INVALID,NOT_APPLIED,UNKNOWN}
    public enum NextAction{REVIEW_OWNED_DIFF,RESOLVE_VERIFICATION_FAILURE,RERUN_VERIFICATION,REVIEW_USER_MODIFICATIONS,ROLLBACK_AVAILABLE,RECOVERY_REQUIRED,MANUAL_COMMIT,REGENERATE_PROPOSALS,RUN_RELEASE_HARDENING}
    public record ProposalSummary(String proposalId,MigrationProposal.Category category,String problemCode,String semanticTarget,List<String>requiredStageRefs,MigrationVerificationResult.ProposalStatus verificationStatus){public ProposalSummary{MigrationApplyPlan.require(proposalId,"migration-proposal-v1");Objects.requireNonNull(category);problemCode=safe(problemCode);semanticTarget=safe(semanticTarget);requiredStageRefs=ids(requiredStageRefs);}}
    public record FileSummary(String logicalPath,MigrationApplyResult.FileStatus applyStatus,CurrentFileState currentState,RollbackState rollbackState,String observedDigest,int editCount,boolean preDirtyTouched,boolean backupValid,List<String>proposalIds,List<String>issues){public FileSummary{logicalPath=MigrationRunPlan.logical(logicalPath);Objects.requireNonNull(applyStatus);Objects.requireNonNull(currentState);Objects.requireNonNull(rollbackState);if(observedDigest!=null)MigrationApplyPlan.require(observedDigest,"sha256");if(editCount<0||editCount>MigrationApplyPlan.MAX_EDITS)throw new IllegalArgumentException("edit count");proposalIds=ids(proposalIds);issues=strings(issues);}}
    public record TransactionEventSummary(long sequence,MigrationApplyTransaction.EventType type,String logicalPath,String observedDigest,String issue){public TransactionEventSummary{if(sequence<0)throw new IllegalArgumentException("sequence");Objects.requireNonNull(type);if(logicalPath!=null)logicalPath=MigrationRunPlan.logical(logicalPath);if(observedDigest!=null)MigrationApplyPlan.require(observedDigest,"sha256");if(issue!=null&&issue.length()>8192)throw new IllegalArgumentException("issue");}}
    public record VerificationCoverage(String verificationPlanRef,String verificationResultRef,MigrationVerificationResult.Status status,int requiredPassed,int requiredTotal,List<StageCoverage>stages,List<ProposalCoverage>proposals,List<CompatibilityCoverage>comparisons){public VerificationCoverage{if(verificationPlanRef!=null)MigrationApplyPlan.require(verificationPlanRef,"migration-verification-plan-v1");if(verificationResultRef!=null)MigrationApplyPlan.require(verificationResultRef,"migration-verification-result-v1");stages=stages==null?List.of():stages.stream().sorted(Comparator.comparingInt(x->x.stageType().ordinal())).toList();proposals=proposals==null?List.of():proposals.stream().sorted(Comparator.comparing(ProposalCoverage::proposalId)).toList();comparisons=comparisons==null?List.of():List.copyOf(comparisons);if(requiredPassed<0||requiredTotal<requiredPassed)throw new IllegalArgumentException("coverage");}}
    public record StageCoverage(String stageRef,MigrationVerificationPlan.StageType stageType,MigrationVerificationPlan.Necessity necessity,MigrationVerificationResult.StageStatus status,List<String>issues){public StageCoverage{MigrationApplyPlan.require(stageRef,"migration-verification-stage-v1");Objects.requireNonNull(stageType);Objects.requireNonNull(necessity);Objects.requireNonNull(status);issues=strings(issues);}}
    public record ProposalCoverage(String proposalId,MigrationVerificationResult.ProposalStatus status,List<String>stageRefs,List<String>issues){public ProposalCoverage{MigrationApplyPlan.require(proposalId,"migration-proposal-v1");Objects.requireNonNull(status);stageRefs=ids(stageRefs);issues=strings(issues);}}
    public record CompatibilityCoverage(String comparisonPlanRef,ComparisonIntent.Axis axis,CompatibilityComparisonReport.Outcome outcome,CompatibilityComparisonReport.Comparability comparability,MigrationVerificationResult.StageStatus status,List<String>targetedFindingStates,List<String>issues){public CompatibilityCoverage{MigrationApplyPlan.require(comparisonPlanRef,"migration-verification-comparison-v1");Objects.requireNonNull(axis);Objects.requireNonNull(outcome);Objects.requireNonNull(comparability);Objects.requireNonNull(status);targetedFindingStates=strings(targetedFindingStates);issues=strings(issues);}}
    public record PreExistingUserState(List<String>staged,List<String>unstaged,List<String>untracked,List<String>conflicted){public PreExistingUserState{staged=paths(staged);unstaged=paths(unstaged);untracked=paths(untracked);conflicted=paths(conflicted);}}
    public record IndexState(List<String>staged,List<String>unstaged,List<String>untracked,List<String>conflicted){public IndexState{staged=paths(staged);unstaged=paths(unstaged);untracked=paths(untracked);conflicted=paths(conflicted);}}
    private static String id(Object...values){List<String>f=new ArrayList<>();for(Object v:values)canonical(f,v);return MigrationVerificationPlan.ref("migration-apply-report-v1",f.toArray(String[]::new));}
    private static void canonical(List<String>out,Object v){if(v==null){out.add("");return;}if(v instanceof Enum<?>e){out.add(e.name());return;}if(v instanceof String s){out.add(s);return;}if(v instanceof Number||v instanceof Boolean){out.add(v.toString());return;}if(v instanceof List<?>l){out.add("[");l.forEach(x->canonical(out,x));out.add("]");return;}if(v.getClass().isRecord()){out.add(v.getClass().getSimpleName());for(var c:v.getClass().getRecordComponents())try{canonical(out,c.getAccessor().invoke(v));}catch(ReflectiveOperationException e){throw new IllegalArgumentException(e);}return;}throw new IllegalArgumentException("unsupported report identity value");}
    private static List<String>ids(List<String>v){return strings(v);}private static List<String>paths(List<String>v){List<String>x=strings(v);x.forEach(MigrationRunPlan::logical);return x;}private static List<String>strings(List<String>v){return v==null?List.of():v.stream().filter(Objects::nonNull).distinct().sorted().toList();}private static String safe(String v){if(v==null||v.length()>1024||v.indexOf('\0')>=0)throw new IllegalArgumentException("bounded text");return v;}
}
